mapper.select:
SELECT e.org_id as orgId, e.user_id as assistantId, e.employee_name as assistantName, SUM( IF( TIMESTAMPDIFF(MINUTE, btp.treat_start_time, btp.treat_end_time)=0, 1, IFNULL(TIME_TO_SEC(TIMEDIFF(DATE_FORMAT(btp.treat_end_time,'%H:%i'), DATE_FORMAT(btp.treat_start_time,'%H:%i')))/60,0) )) AS treatMatchingTimeAsAssistant1, sum( IFNULL( btp.actualWorkload, 0 )) AS treatMatchingActualWorkloadAsAssistant1, SUM( IFNULL( btp.refundWorkload, 0 )) AS treatMatchingRefundWorkloadAsAssistant1 FROM ( SELECT bup.user_id, bup.org_id, be.employee_name FROM base_user_post bup LEFT JOIN base_employee be ON bup.user_id = be.user_id WHERE bup.group_id = 4 ) e LEFT JOIN ( SELECT btp.treatment_id, btp.org_id, btp.treat_start_time, btp.treat_end_time, ${assistant}, IFNULL( bbd.actualWorkload, 0 ) AS actualWorkload, IFNULL( bf.refundWorkload, 0 ) AS refundWorkload FROM base_treatment_process btp LEFT JOIN ( SELECT SUM( bbd.originalAmount - bbd.discount_amount ) AS actualWorkload, bbd.treatment_id FROM ( SELECT bb.treatment_id, bbd.price * bbd.quantity AS originalAmount, bbd.discount_amount FROM base_bill_detail bbd LEFT JOIN (select bb.treatment_id,bb.bill_id,bb.bill_date from base_bill bb where bb.bill_date is not null) bb ON bbd.bill_id = bb.bill_id WHERE bbd.executor_id IS NOT NULL ) bbd GROUP BY bbd.treatment_id ) bbd ON btp.treatment_id = bbd.treatment_id LEFT JOIN ( SELECT br.treatment_id, SUM( br.refund_amount ) AS refundWorkload FROM base_refund br GROUP BY br.treatment_id ) bf ON btp.treatment_id = bf.treatment_id
AND btp.treat_end_time IS NOT NULL AND ${assistant} IS NOT NULL
AND DATE_FORMAT( btp.treat_start_time, '%Y-%m-%d' ) >= #{query.startDate}
AND DATE_FORMAT( btp.treat_start_time, '%Y-%m-%d' ) <= #{query.endDate}
AND DATE_FORMAT( btp.treat_start_time, '%Y-%m' ) >= #{query.startDate}
AND DATE_FORMAT( btp.treat_start_time, '%Y-%m' ) <= #{query.endDate}
AND DATE_FORMAT( btp.treat_start_time, '%Y' ) >= #{query.startDate}
AND DATE_FORMAT( btp.treat_start_time, '%Y' ) <= #{query.endDate}
GROUP BY btp.treatment_id ) btp ON e.user_id = ${assistant} AND e.org_id = btp.org_id
and e.org_id = #{query.orgId}
and e.user_id in
#{item}
GROUP BY e.org_id, e.user_id ORDER BY treatMatchingTimeAsAssistant1 DESC

SELECT e.org_id as orgId, e.user_id as assistantId, e.employee_name as assistantName, SUM( IF(TIMESTAMPDIFF(MINUTE, btp.treat_start_time, btp.treat_end_time)=0,1,IFNULL(TIMESTAMPDIFF( MINUTE, btp.treat_start_time, btp.treat_end_time),0))) AS treatMatchingTimeAsAssistant1, sum( IFNULL( btp.actualWorkload, 0 )) AS treatMatchingActualWorkloadAsAssistant1, SUM( IFNULL( btp.refundWorkload, 0 )) AS treatMatchingRefundWorkloadAsAssistant1, SUM( IF(TIMESTAMPDIFF( MINUTE, btp1.treat_start_time, btp1.treat_end_time)=0,1,IFNULL(TIMESTAMPDIFF( MINUTE, btp1.treat_start_time, btp1.treat_end_time),0))) AS treatMatchingTimeAsAssistant2, SUM( IFNULL( btp1.actualWorkload, 0 )) AS treatMatchingActualWorkloadAsAssistant2, SUM( IFNULL( btp1.refundWorkload, 0 )) AS treatMatchingRefundWorkloadAsAssistant2, SUM( IF(TIMESTAMPDIFF( MINUTE, btp2.treat_start_time, btp2.treat_end_time)=0,1,IFNULL(TIMESTAMPDIFF( MINUTE, btp2.treat_start_time, btp2.treat_end_time),0))) AS treatMatchingTimeAsAssistant3, SUM( IFNULL( btp2.actualWorkload, 0 )) AS treatMatchingActualWorkloadAsAssistant3, SUM( IFNULL( btp2.refundWorkload, 0 ) ) AS treatMatchingRefundWorkloadAsAssistant3 FROM ( SELECT bup.user_id, bup.org_id, be.employee_name FROM base_user_post bup LEFT JOIN base_employee be ON bup.user_id = be.user_id WHERE bup.group_id = 4 -- 全部助手 ) e LEFT JOIN ( SELECT btp.treatment_id, btp.org_id, btp.treat_start_time, btp.treat_end_time, btp.assistant_1, IFNULL( bbd.actualWorkload, 0 ) AS actualWorkload, IFNULL( bf.refundWorkload, 0 ) AS refundWorkload FROM base_treatment_process btp LEFT JOIN ( SELECT SUM( bbd.originalAmount - bbd.discount_amount ) AS actualWorkload, bbd.treatment_id FROM ( SELECT bb.treatment_id, bbd.price * bbd.quantity AS originalAmount, bbd.discount_amount FROM base_bill_detail bbd LEFT JOIN base_bill bb ON bbd.bill_id = bb.bill_id WHERE bbd.executor_id IS NOT NULL ) bbd GROUP BY bbd.treatment_id ) bbd ON btp.treatment_id = bbd.treatment_id LEFT JOIN ( SELECT br.treatment_id, SUM( br.refund_amount ) AS refundWorkload FROM base_refund br GROUP BY br.treatment_id ) bf ON btp.treatment_id = bf.treatment_id
AND btp.treat_end_time IS NOT NULL AND btp.assistant_1 IS NOT NULL
AND DATE_FORMAT( btp.treat_start_time, '%Y-%m-%d' ) >= #{query.startDate}
AND DATE_FORMAT( btp.treat_start_time, '%Y-%m-%d' ) <= #{query.endDate}
AND DATE_FORMAT( btp.treat_start_time, '%Y-%m' ) >= #{query.startDate}
AND DATE_FORMAT( btp.treat_start_time, '%Y-%m' ) <= #{query.endDate}
AND DATE_FORMAT( btp.treat_start_time, '%Y' ) >= #{query.startDate}
AND DATE_FORMAT( btp.treat_start_time, '%Y' ) <= #{query.endDate}
GROUP BY btp.treatment_id ) btp ON e.user_id = btp.assistant_1 AND e.org_id = btp.org_id LEFT JOIN ( SELECT btp.treatment_id, btp.org_id, btp.treat_start_time, btp.treat_end_time, btp.assistant_2, IFNULL( bbd.actualWorkload, 0 ) AS actualWorkload, IFNULL( bf.refundWorkload, 0 ) AS refundWorkload FROM base_treatment_process btp LEFT JOIN ( SELECT SUM( bbd.originalAmount - bbd.discount_amount ) AS actualWorkload, bbd.treatment_id FROM ( SELECT bb.treatment_id, bbd.price * bbd.quantity AS originalAmount, bbd.discount_amount FROM base_bill_detail bbd LEFT JOIN base_bill bb ON bbd.bill_id = bb.bill_id WHERE bbd.executor_id IS NOT NULL ) bbd GROUP BY bbd.treatment_id ) bbd ON btp.treatment_id = bbd.treatment_id LEFT JOIN ( SELECT br.treatment_id, SUM( br.refund_amount ) AS refundWorkload FROM base_refund br GROUP BY br.treatment_id ) bf ON btp.treatment_id = bf.treatment_id
and btp.treat_end_time IS NOT NULL and btp.assistant_1 IS NOT NULL
AND DATE_FORMAT( btp.treat_start_time, '%Y-%m-%d' ) >= #{query.startDate}
AND DATE_FORMAT( btp.treat_start_time, '%Y-%m-%d' ) <= #{query.endDate}
AND DATE_FORMAT( btp.treat_start_time, '%Y-%m' ) >= #{query.startDate}
AND DATE_FORMAT( btp.treat_start_time, '%Y-%m' ) <= #{query.endDate}
AND DATE_FORMAT( btp.treat_start_time, '%Y' ) >= #{query.startDate}
AND DATE_FORMAT( btp.treat_start_time, '%Y' ) <= #{query.endDate}
GROUP BY btp.treatment_id ) btp1 ON e.user_id = btp1.assistant_2 AND e.org_id = btp1.org_id LEFT JOIN ( SELECT btp.treatment_id, btp.org_id, btp.treat_start_time, btp.treat_end_time, btp.assistant_3, IFNULL( bbd.actualWorkload, 0 ) AS actualWorkload, IFNULL( bf.refundWorkload, 0 ) AS refundWorkload FROM base_treatment_process btp LEFT JOIN ( SELECT SUM( bbd.originalAmount - bbd.discount_amount ) AS actualWorkload, bbd.treatment_id FROM ( SELECT bb.treatment_id, bbd.price * bbd.quantity AS originalAmount, bbd.discount_amount FROM base_bill_detail bbd LEFT JOIN base_bill bb ON bbd.bill_id = bb.bill_id WHERE bbd.executor_id IS NOT NULL ) bbd GROUP BY bbd.treatment_id ) bbd ON btp.treatment_id = bbd.treatment_id LEFT JOIN ( SELECT br.treatment_id, SUM( br.refund_amount ) AS refundWorkload FROM base_refund br GROUP BY br.treatment_id ) bf ON btp.treatment_id = bf.treatment_id
and btp.treat_end_time IS NOT NULL and btp.assistant_1 IS NOT NULL
AND DATE_FORMAT( btp.treat_start_time, '%Y-%m-%d' ) >= #{query.startDate}
AND DATE_FORMAT( btp.treat_start_time, '%Y-%m-%d' ) <= #{query.endDate}
AND DATE_FORMAT( btp.treat_start_time, '%Y-%m' ) >= #{query.startDate}
AND DATE_FORMAT( btp.treat_start_time, '%Y-%m' ) <= #{query.endDate}
AND DATE_FORMAT( btp.treat_start_time, '%Y' ) >= #{query.startDate}
AND DATE_FORMAT( btp.treat_start_time, '%Y' ) <= #{query.endDate}
GROUP BY btp.treatment_id ) btp2 ON e.user_id = btp2.assistant_3 AND e.org_id = btp2.org_id
and e.org_id = #{query.orgId}
and e.user_id in
#{item}
GROUP BY e.org_id, e.user_id

SELECT edi.employeeId, edi.employeeName, edi.totalShiftTime, edi.totalTreatmentTime, edi.firstVisitNum, edi.treatVisitsTimes, CONVERT ( edi.totalActualAmount / edi.treatVisitsTimes, DECIMAL ( 19, 2 )) AS averageConsumption, edi.treatVisitsNum, CONVERT ( edi.totalActualAmount / edi.treatVisitsNum, DECIMAL ( 19, 2 )) AS perCapitaConsumption, edi.appointmentsNum, edi.visitArrivedTimes, edi.appointmentModifyTimes, edi.appointmentCancelTimes FROM ( SELECT bup.org_id AS orgId, bup.user_id AS employeeId, IFNULL( be.employee_name, '--' ) AS employeeName, IFNULL( bes.totalShiftTime, 0 ) AS totalShiftTime, IFNULL( btp.totalTreatmentTime, 0 ) AS totalTreatmentTime, IFNULL( btp.treatVisitsTimes, 0 ) AS treatVisitsTimes, IFNULL( btp.treatVisitsNum, 0 ) AS treatVisitsNum, IFNULL( btp1.firstVisitNum, 0 ) AS firstVisitNum, IFNULL( btp2.appointmentsNum, 0 ) AS appointmentsNum, IFNULL( btp3.appointmentModifyTimes, 0 ) AS appointmentModifyTimes, IFNULL( btp4.appointmentCancelTimes, 0 ) AS appointmentCancelTimes, IFNULL( btp5.visitArrivedTimes, 0 ) AS visitArrivedTimes, IFNULL( btp6.totalActualAmount, 0 ) AS totalActualAmount FROM ( SELECT bup.org_id, bup.user_id FROM base_user_post bup WHERE bup.group_id = 3 GROUP BY bup.org_id, bup.user_id ) bup LEFT JOIN base_employee be ON bup.user_id = be.user_id LEFT JOIN ( SELECT bes.user_id, bes.org_id, SUM( bes.schedule_duration ) AS totalShiftTime FROM base_employee_schedule bes
and DATE_FORMAT( bes.schedule_date, '%Y-%m-%d' ) >= #{query.startDate}
and DATE_FORMAT( bes.schedule_date, '%Y-%m-%d' ) <= #{query.endDate}
GROUP BY bes.org_id, bes.user_id ) bes ON bup.user_id = bes.user_id AND bup.org_id = bes.org_id LEFT JOIN ( SELECT btp.org_id, btp.registered_dentist_id, SUM( IF ( TIMESTAMPDIFF( MINUTE, btp.treat_start_time, btp.treat_end_time ) = 0, 1, TIMESTAMPDIFF( MINUTE, btp.treat_start_time, btp.treat_end_time ))) AS totalTreatmentTime, COUNT( btp.treatment_id ) AS treatVisitsTimes, COUNT( DISTINCT btp.patient_id ) AS treatVisitsNum FROM base_treatment_process btp
and btp.treat_end_time IS NOT NULL
and DATE_FORMAT( btp.treat_start_time, '%Y-%m-%d' ) >= #{query.startDate}
and DATE_FORMAT( btp.treat_start_time, '%Y-%m-%d' ) <= #{query.endDate}
GROUP BY btp.org_id, btp.registered_dentist_id ) btp ON bup.user_id = btp.registered_dentist_id AND bup.org_id = btp.org_id LEFT JOIN ( SELECT btp.org_id, btp.registered_dentist_id, COUNT( DISTINCT btp.patient_id ) AS firstVisitNum FROM base_treatment_process btp
and btp.treat_type = 0 and btp.treat_end_time IS NOT NULL
and DATE_FORMAT( btp.treat_start_time, '%Y-%m-%d' ) >= #{query.startDate}
and DATE_FORMAT( btp.treat_start_time, '%Y-%m-%d' ) <= #{query.endDate}
GROUP BY btp.org_id, btp.registered_dentist_id ) btp1 ON bup.user_id = btp1.registered_dentist_id AND bup.org_id = btp1.org_id LEFT JOIN ( SELECT btp.org_id, btp.appoint_dentist_id, COUNT( btp.appoint_dentist_id ) AS appointmentsNum FROM base_treatment_process btp
and btp.appoint_status != 2
and DATE_FORMAT( btp.appoint_start_time, '%Y-%m-%d' ) >= #{query.startDate}
and DATE_FORMAT( btp.appoint_start_time, '%Y-%m-%d' ) <= #{query.endDate}
GROUP BY btp.org_id, btp.appoint_dentist_id ) btp2 ON bup.user_id = btp2.appoint_dentist_id AND bup.org_id = btp2.org_id LEFT JOIN ( SELECT btp.org_id, btp.dentist_id, count(btp.appointment_id) AS appointmentModifyTimes FROM base_appointment_modify btp
and DATE_FORMAT( btp.crt_time, '%Y-%m-%d' ) >= #{query.startDate}
and DATE_FORMAT( btp.crt_time, '%Y-%m-%d' ) <= #{query.endDate}
GROUP BY btp.org_id, btp.dentist_id ) btp3 ON bup.user_id = btp3.dentist_id AND bup.org_id = btp3.org_id LEFT JOIN ( SELECT btp.org_id, btp.appoint_dentist_id, COUNT( btp.appointment_id ) AS appointmentCancelTimes FROM base_treatment_process btp
and btp.appoint_status = 2
and DATE_FORMAT( btp.appoint_start_time, '%Y-%m-%d' ) >= #{query.startDate}
and DATE_FORMAT( btp.appoint_start_time, '%Y-%m-%d' ) <= #{query.endDate}
GROUP BY btp.org_id, btp.registered_dentist_id, btp.appoint_dentist_id ) btp4 ON bup.user_id = btp4.appoint_dentist_id AND bup.org_id = btp4.org_id LEFT JOIN ( SELECT btp.org_id, btp.appoint_dentist_id, COUNT( appointment_id ) AS visitArrivedTimes FROM base_treatment_process btp
and btp.appoint_dentist_id = btp.registered_dentist_id
and DATE_FORMAT( btp.appoint_start_time, '%Y-%m-%d' ) >= #{query.startDate}
and DATE_FORMAT( btp.appoint_start_time, '%Y-%m-%d' ) <= #{query.endDate}
GROUP BY btp.org_id, btp.appoint_dentist_id ) btp5 ON bup.user_id = btp5.appoint_dentist_id AND bup.org_id = btp5.org_id LEFT JOIN ( SELECT btp.org_id, btp.registered_dentist_id, SUM( btp.actualAmount ) AS totalActualAmount FROM ( SELECT btp.registered_dentist_id, btp.org_id, IFNULL( bb.actual_amount, 0 ) AS actualAmount FROM base_treatment_process btp LEFT JOIN base_bill bb ON btp.treatment_id = bb.treatment_id
and btp.treat_end_time IS NOT NULL
and DATE_FORMAT( btp.treat_start_time, '%Y-%m-%d' ) >= #{query.startDate}
and DATE_FORMAT( btp.treat_start_time, '%Y-%m-%d' ) <= #{query.endDate}
) btp GROUP BY btp.org_id, btp.registered_dentist_id ) btp6 ON bup.user_id = btp6.registered_dentist_id AND bup.org_id = btp6.org_id ) edi
and edi.orgId = #{query.orgId}
and edi.employeeId in
#{item}
GROUP BY edi.orgId, edi.employeeId
